window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-97bf67619baee734"]={"versions": [{"id": "FIG-97bf67619baee734", "releases": ["R1.3.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenlayout- und Protokollformat-Diagramm zur Veranschaulichung des AUTOSAR E2E-Sicherheitsprotokollkonzepts (End-to-End-Kommunikationsschutz). Es zeigt die Kapselung bzw. Zusammensetzung eines Nutzdaten-Elements (App data element) und der zugehörigen E2E-Sicherheitsfelder zu einer geschützten Dateneinheit auf RTE-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in folgende Datenelemente und Felder:</p>\n<ul class=\"fig-list\"><li>App data element: Das ursprüngliche Anwendungsdatenelement (Payload) der Applikationsebene.\n</li><li>E2E Header: Der dem Nutzdatenelement angefügte bzw. beigestellte E2E-Sicherheits-Header.\n</li><li>Control Fields (CF): Detailstruktur des E2E-Headers, unterteilt in Einzelfelder <code>CF1</code>, <code>CF2</code>, <code>...</code> bis <code>CF(x)</code> (typischerweise Prüfsummen wie CRC, Sequenzzähler/Counter und Daten-IDs).\n</li><li>Data element for RTE: Die Gesamteinheit aus <code>App data element</code> und dem nachfolgenden <code>E2E Header</code> (zusammengefasst durch eine geschweifte Klammer), welche als geschütztes Datenelement über die Runtime Environment (RTE) übertragen wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Format- und Schachtelungsbeziehung dar:</p>\n<ol class=\"fig-list\"><li>Das ungeschützte <code>App data element</code> wird durch Hinzufügen des <code>E2E Header</code> geschützt.\n</li><li>Der <code>E2E Header</code> expandiert in eine Reihe von Steuerfeldern <code>CF1</code> bis <code>CF(x)</code>.\n</li><li>Die Kombination aus Anwendungsdaten und Steuerfeldern bildet zusammen das <code>Data element for RTE</code> für die sichere Weiterleitung im Kommunikationsstapel.\n</li><li>Empfängerseitig werden die Kontrollfelder <code>CF1</code> bis <code>CF(x)</code> ausgewertet, um Übertragungsfehler, Datenverluste, Wiederholungen oder Vertauschungen des <code>App data element</code> zu erkennen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung visualisiert ein exemplarisches Layout des E2E-Schutzes gemäß AUTOSAR E2E Protocol. Zu beachten für Spezifikation und Implementierung:</p>\n<ul class=\"fig-list\"><li>Die Anordnung des <code>E2E Header</code> hinter dem <code>App data element</code> ist exemplarisch; je nach E2E-Profil und Konfiguration kann der Header oder einzelne Steuerfelder auch an anderer Stelle (z. B. am Anfang oder an festen Byte-Offsets) platziert sein.\n</li><li>Die Kontrollfelder <code>CF1</code> bis <code>CF(x)</code> entsprechen den profilspezifischen Prüfdaten (z. B. CRC-8/16/32, Alive Counter).\n</li><li>Die RTE transportiert das zusammengesetzte <code>Data element for RTE</code> als zusammenhängende Datenstruktur zwischen Software-Komponenten bzw. zum Communication Stack (Com/PduR).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-06c73c33104cbfd8", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenlayout- und Protokollformat-Diagramm zur Veranschaulichung des AUTOSAR E2E-Sicherheitsprotokollkonzepts (End-to-End-Kommunikationsschutz). Es zeigt die Kapselung bzw. Zusammensetzung eines Nutzdaten-Elements (App data element) und der zugehörigen E2E-Sicherheitsfelder zu einer geschützten Dateneinheit auf RTE-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in folgende Datenelemente und Felder:</p>\n<ul class=\"fig-list\"><li>App data element: Das ursprüngliche Anwendungsdatenelement (Payload) der Applikationsebene.\n</li><li>E2E Header: Der dem Nutzdatenelement angefügte bzw. beigestellte E2E-Sicherheits-Header.\n</li><li>Control Fields (CF): Detailstruktur des E2E-Headers, unterteilt in Einzelfelder <code>CF1</code>, <code>CF2</code>, <code>...</code> bis <code>CF(x)</code> (typischerweise Prüfsummen wie CRC, Sequenzzähler/Counter und Daten-IDs).\n</li><li>Data element for RTE: Die Gesamteinheit aus <code>App data element</code> und dem nachfolgenden <code>E2E Header</code> (zusammengefasst durch eine geschweifte Klammer), welche als geschütztes Datenelement über die Runtime Environment (RTE) übertragen wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Format- und Schachtelungsbeziehung dar:</p>\n<ol class=\"fig-list\"><li>Das ungeschützte <code>App data element</code> wird durch Hinzufügen des <code>E2E Header</code> geschützt.\n</li><li>Der <code>E2E Header</code> expandiert in eine Reihe von Steuerfeldern <code>CF1</code> bis <code>CF(x)</code>.\n</li><li>Die Kombination aus Anwendungsdaten und Steuerfeldern bildet zusammen das <code>Data element for RTE</code> für die sichere Weiterleitung im Kommunikationsstapel.\n</li><li>Empfängerseitig werden die Kontrollfelder <code>CF1</code> bis <code>CF(x)</code> ausgewertet, um Übertragungsfehler, Datenverluste, Wiederholungen oder Vertauschungen des <code>App data element</code> zu erkennen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung visualisiert ein exemplarisches Layout des E2E-Schutzes gemäß AUTOSAR E2E Protocol. Zu beachten für Spezifikation und Implementierung:</p>\n<ul class=\"fig-list\"><li>Die Anordnung des <code>E2E Header</code> hinter dem <code>App data element</code> ist exemplarisch; je nach E2E-Profil und Konfiguration kann der Header oder einzelne Steuerfelder auch an anderer Stelle (z. B. am Anfang oder an festen Byte-Offsets) platziert sein.\n</li><li>Die Kontrollfelder <code>CF1</code> bis <code>CF(x)</code> entsprechen den profilspezifischen Prüfdaten (z. B. CRC-8/16/32, Alive Counter).\n</li><li>Die RTE transportiert das zusammengesetzte <code>Data element for RTE</code> als zusammenhängende Datenstruktur zwischen Software-Komponenten bzw. zum Communication Stack (Com/PduR).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-97bf67619baee734", "to": "FIG-06c73c33104cbfd8", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-06c73c33104cbfd8", "to": "FIG-97bf67619baee734", "fr": "R1.5.1", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
